@spec vm_undo_label_spec  src=tests/specs/vm_undo_label_spec.lua  loc=123  cases=3
@exercises trackerView (h.vm), editCursor (h.ec), midiManager (h.fm)
@surface   vm:setGridSize, ec:setPos, fm:dump, vm:unautomateParam, vm:hideExtraCol
@harness   mk{seed.notes, seed.ccs}

# Intent
  The undo label sits on the verb, not on the command. A command registered
  with registerAll's tuple form labels its own body; where that body only opens
  a modal, the edit lands in the callback frames later, outside the block. So
  the verbs below carry their labels themselves, and every entry point -- key,
  menu, confirm callback, patternEditor's own registration -- picks one up.

# Helpers
  @fn collectLabels(h)  @ 13-21
      -- util.atomic reads reaper.Undo_BeginBlock at call time, so a stub installed
      -- after the wrap still counts. Outermost blocks only: an inner block (the
      -- hideExtraCol inside unautomateParam) collapses into the verb's.
  @fn offGridTake(harness)  @ 27-40
      -- One note 5 ppq past row 2 (logPerRow 60 at rpb 4), so every quantize verb
      -- has a real move to make: onset back to 120, either as intent or as delay.
  @fn ccColIndex(h, cc)  @ 59-63

# Cases
  @case 'every quantize verb opens one labelled block -- whole-take scope included'  [harness]  @ 68-81
  @case 'unautomateParam labels its own block -- the confirm callback lands outside the command'  [harness]  @ 85-103
  @case 'hideExtraCol labels its own block'  [harness]  @ 107-120

# Uses (outbound edges)
  @use call vm:setGridSize  @ 38,95,113
  @use call ec:setPos  @ 73,96,114
  @use call fm:dump  @ 77
  @use call vm:unautomateParam  @ 98
  @use call vm:hideExtraCol  @ 116

